# owner: platform
"""Seating rows built from a list of students."""

from typing import Iterable, List

from rosterkit.models import Student


def _name_key(student: Student) -> tuple:
    last = student.last_name.casefold()
    return (last, student.first_name.casefold())


def _row_line(number: int, row: List[Student]) -> str:
    names = " | ".join(item.display_name for item in row)
    return f"Row {number}: {names}"


def _check(people: List[Student], seats: int) -> None:
    if seats <= 0:
        raise ValueError("seats_per_row must be positive")
    if not people:
        raise ValueError("no students to seat")


def _chunks(people: List[Student], size: int) -> list:
    return [
        people[start:start + size]
        for start in range(0, len(people), size)
    ]


# ---
def seat_students(
    students: Iterable[Student], seats_per_row: int
) -> List[str]:
    """One text line per row, sorted by last name."""
    people = sorted(students, key=_name_key)
    _check(people, seats_per_row)
    rows = _chunks(people, seats_per_row)
    return [_row_line(n, r) for n, r in enumerate(rows, 1)]
EOF
cat > tests/test_seating.py <<'EOF'
# owner: platform
import unittest

from rosterkit.seating import seat_students
from rosterkit.models import Student


def _student(last, first, number="1"):
    return Student(number, last, first, "A")


def _class():
    return [
        _student("Halloway", "Juno", "2"),
        _student("Dunmere", "Piet", "1"),
        _student("Quillon", "Ada", "3")
    ]


class SeatingTests(unittest.TestCase):
    # ---
    def test_rows_sorted_by_last_name(self):
        self.assertEqual(
            seat_students(_class(), 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Quillon, Ada"
            ]
        )

    # ---
    def test_first_name_breaks_ties(self):
        pair = [_student("Fox", "Zed"), _student("Fox", "Amy")]
        self.assertEqual(
            seat_students(pair, 5),
            ["Row 1: Fox, Amy | Fox, Zed"]
        )

    # ---
    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_students(_class(), 0)

    # ---
    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_students(_class(), -3)

    # ---
    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_students([], 4)
